    "title": {
      "type": "Text",
      "props": {
        "text": "Your Transatlantic Multi-City Flight Plan",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This plan outlines the booking process and pre-purchase checks for a two-adult, multi-city trip in Economy class from New York (JFK) to London (LHR), then to Rome (FCO), and returning to New York (JFK) in May 2025. The focus is on Star Alliance carriers with at least one checked bag included and layovers under four hours.",
        "variant": "body"
      },
      "children": []
    },
    "image_gallery": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "justify": "between"
      },
      "children": [
        "image_london",
        "image_rome",
        "image_ny"
      ]
    },
    "image_london": {
      "type": "Image",
      "props": {
        "url": "https://storage.googleapis.com/generative-ai-dev-llm-testing-resources/genui/r_000008_01_1_london_bridge.jpg",
        "fit": "cover",
        "height": 120,
        "flex": 1
      },
      "children": []
    },
    "image_rome": {
      "type": "Image",
      "props": {
        "url": "https://storage.googleapis.com/generative-ai-dev-llm-testing-resources/genui/r_000008_01_2_rome_colosseum.jpg",
