        "flex": 1
      },
      "children": []
    },
    "image_ny": {
      "type": "Image",
      "props": {
        "url": "https://storage.googleapis.com/generative-ai-dev-llm-testing-resources/genui/r_000008_01_3_newyork_skyline.jpg",
        "fit": "cover",
        "height": 120,
        "flex": 1
      },
      "children": []
    },
    "planning_context_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "planning_context_title",
        "planning_context_text"
      ]
    },
    "planning_context_title": {
      "type": "Text",
      "props": {
        "text": "Planning Context for U.S. Travelers",
        "variant": "h2"
      },
      "children": []
    },
    "planning_context_text": {
      "type": "Text",
      "props": {
        "text": "This checklist assumes both adult passengers are U.S. citizens traveling with U.S. passports. Visa and entry requirements can vary significantly based on nationality, so it is crucial to verify the rules for your specific citizenship and travel documents.",
        "variant": "body"
      },
      "children": []
    },
    "checklist_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg"
      },
      "children": [
        "checklist_title",
        "checklist_intro",
        "travel_docs_stack",
        "airline_fare_stack",
        "itinerary_details_stack"
      ]
    },
    "checklist_title": {
      "type": "Text",
      "props": {
        "text": "Pre-Booking Verification Checklist",
        "variant": "h2"
      },
      "children": []
    },
    "checklist_intro": {
      "type": "Text",
      "props": {
        "text": "Before committing to a purchase, review these critical details to avoid unexpected costs or travel disruptions.",
        "variant": "body"
      },
      "children": []
    },
    "travel_docs_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "travel_docs_title",
        "travel_docs_item1",
        "travel_docs_item2",
        "travel_docs_item3"
      ]
